27	        Arrays.sort(edges);
28	        UnionFind uf = new UnionFind(vertices);
29	        int mstWeight = 0;
30	
31	        System.out.println("Kruskal's MST (" + vertices + " vertices, " + edges.length + " edges)");
32	        System.out.println();
33	
34	        for (Edge e : edges) {
